contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint sendAmount, uint destAmount) public payable {
        require(address(this).balance >= sendAmount, "not enough balance");
        require(target != address(0), "target zero");

        address ownerBefore = c.owner();
        uint depositsBefore = c.depositsCount();
        uint cBalanceBefore = address(c).balance;
        uint targetBalanceBefore = target.balance;

        bool reverted;
        try c.sendMoney{value: sendAmount}(target, destAmount, "") {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();
        uint depositsAfter = c.depositsCount();
        uint cBalanceAfter = address(c).balance;
        uint targetBalanceAfter = target.balance;

        if (!reverted) {
            assert(ownerAfter == ownerBefore &&
                   depositsAfter == depositsBefore &&
                   cBalanceAfter + destAmount == cBalanceBefore &&
                   targetBalanceAfter == targetBalanceBefore + destAmount);
        }
    }

    receive() external payable {}
}

