contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, address target, uint value, bytes memory data) public payable {
        require(amount > 0 && address(this).balance >= amount);

        // Ensure the test contract is not the owner by making the owner address differ.
        // Only the contract that deployed c can be c.owner; since this test contract is
        // deployed separately and c is deployed by the checker before this InvMutTest,
        // the only way this InvMutTest is c.owner is if its address equals c.owner().
        // We require the opposite of the owner-check outcome to be interesting: 
        // make sure this InvMutTest is NOT c.owner().
        address owner = c.owner();
        require(owner != address(this));

        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Non-owner attempts must revert on all owner-only mutators.
        bool revertedWithdrawAll;
        try c.withdrawAll() { revertedWithdrawAll = false; } catch { revertedWithdrawAll = true; }

        bool revertedWithdraw;
        try c.withdraw(value) { revertedWithdraw = false; } catch { revertedWithdraw = true; }

        bool revertedSendMoney;
        try c.sendMoney(target, value, data) { revertedSendMoney = false; } catch { revertedSendMoney = true; }

        // A plain deposit from a non-owner must succeed and increment depositsCount by one,
        // increasing c's balance by exactly amount.
        c.depositsCount(); // read-only call to keep the observable path
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok, "deposit failed");

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        assert(
            revertedWithdrawAll && revertedWithdraw && revertedSendMoney &&
            afterDeposits == beforeDeposits + 1 &&
            afterBalance == beforeBalance + amount
        );
    }

    receive() external payable {}
}

