        assert(address(this).balance == ownerBalanceBefore + address(c).balance + depositAmount);
        // depositsCount must remain unchanged by withdrawal
        assert(c.depositsCount() == depositsBeforeWithdraw);

        // Additionally, send input withdrawalAmount via sendMoney to a benign target
        uint ethBefore = address(this).balance;
        c.sendMoney(address(this), withdrawalAmount, "");
        assert(address(this).balance == ethBefore + withdrawalAmount);
    }

    receive() external payable {}
}

