            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // After values must equal before values for non-owner
        assert(
            recvReverted &&
            withdrawReverted &&
            withdrawAllReverted &&
            sendMoneyReverted &&
            c.depositsCount() == beforeDeposits &&
            address(c).balance == beforeBalance
        );
    }
